//! wgpu backend/device lifecycle, residency and budgets; GPU API types hidden from
//! document/contracts.
//!
//! Implements the pigment-owned `RenderBackend` port (`hsk_studio_pigment::render_plan`) as
//! [`GpuBackend`]. The plan IR, `StudioBlendMode`, the receipt and the reference blend arithmetic
//! (`hsk_studio_pigment::blend_math`) live in pigment (CX-CAP-001); this crate adds headless
//! device acquisition, generation/loss handling, byte-accounted residency and the WGSL compute
//! pass. No wgpu type appears in any public signature (STU-ARC-002); a missing adapter is the
//! typed `Unavailable`, not a silent CPU fallback (test admission_refusals_run_without_adapter).
#![forbid(unsafe_code)]
pub mod device;
pub mod error;
mod ext;
mod fx;
mod kernel;
pub mod plan_sink;
pub mod report;
pub mod residency;

pub use device::{AdapterKind, BackendChoice, DeviceInfo, DeviceOptions, GpuContext};
pub use error::{GpuError, Reason};
pub use kernel::{gpu_adjust_supported, gpu_blend_qualifies, gpu_blend_supported};
pub use plan_sink::{GpuBackend, GpuStats, RENDERER_NAME, RENDERER_VERSION};
/// Shared-device output (feature `shared-device`, lane SMB-RENDER-GPU-SHARED-DEVICE): the only
/// public items that name wgpu types; see `plan_sink::shared`.
#[cfg(feature = "shared-device")]
pub use plan_sink::shared::{DESCRIPTOR as SHARED_DESCRIPTOR, SharedDevice, TARGET_FORMAT};
pub use report::{outcome_of, report};
pub use residency::{Reservation, ReservationId, Residency, ResidentKey};

/// V4-04 compile check (R6 review A): in a default build no fault-injection hook is a public item,
/// so every snippet below fails to compile with E0599 (no function or method found). The item is
/// compiled out with `--features test-faults`, where the hooks exist and the snippets would compile.
///
/// ```compile_fail,E0599
/// let _ = hsk_studio_render_gpu::GpuBackend::with_injected_loss(Default::default(), 1);
/// ```
///
/// ```compile_fail,E0599
/// let _ = hsk_studio_render_gpu::GpuBackend::with_shader_source(Default::default(), "");
/// ```
///
/// ```compile_fail,E0599
/// let backend = hsk_studio_render_gpu::GpuBackend::new(Default::default());
/// let _ = backend.simulate_device_loss();
/// ```
///
/// ```compile_fail,E0599
/// fn lose(context: &hsk_studio_render_gpu::GpuContext) {
///     context.simulate_device_loss();
/// }
/// ```
#[cfg(not(feature = "test-faults"))]
#[allow(dead_code)]
const FAULT_HOOKS_ARE_NOT_PUBLIC: () = ();

pub const DESCRIPTOR: &str = r#"{"module":"STUDIO-MODULE-RENDER_GPU","version":1,"renderer":"hsk-studio-render-gpu/0.1","operation":"execute_render_plan_to_tile_sink","api":"impl RenderBackend<NoVector> for GpuBackend (pigment render_plan port, including extension_exactness and execute_extended); GpuBackend::new(DeviceOptions) returns a backend (not a Result) that holds Ready|Lost|Unavailable|Failed, where failure() is the typed pipeline failure of a present adapter (tests admission_refusals_run_without_adapter, pipeline_failure_is_typed_and_fails_the_gpu_gate); execute_detailed and execute_extended_detailed return (RenderReceipt, GpuStats); reacquire(cancel) is the only recovery; report(result, correlation, revision, cancel, observe, sink) emits one terminal Observe frame","command":"render-gpu-consumer --descriptor | --probe | --selftest","device":{"acquire":"headless: wgpu instance + adapter + device with no surface, no window, no focus; downlevel limits; validation layers off","backends":"auto (one backend per instance in platform order: windows dx12 then vulkan, apple metal, else vulkan)|vulkan|dx12|metal|none (none = forced Unavailable(no_adapter))","generation":"u64, 1 on first acquire, +1 on every reacquire; a lost device latches DeviceLost{generation} for every later execute until reacquire","loss":"the wgpu device-lost callback is the only latch; the backend polls the device before every execute and state query, so a destroyed device is detected by that callback; simulate_device_loss = wgpu Device::destroy only and does not set the latch (test device_destroy_is_detected_by_the_lost_callback fails when the callback wiring is removed); driver-initiated loss (TDR, adapter removal) not proven","unavailable":"no adapter -> Unavailable(no_adapter) (after admission); adapter without device -> no_device; request timeout -> adapter_timeout; there is no CPU fallback (test admission_refusals_run_without_adapter: a valid plan on the none backend is Unavailable(no_adapter) with no sink call)","pipeline_failure":"adapter and device present but the WGSL shader or compute pipeline fails validation -> GpuError::Pipeline(shader_validation) in its own Failed state (GpuBackend::failure), at the port Unavailable(shader_validation); it is not reported as no_adapter or no_device, so a test or probe fails instead of skipping (test pipeline_failure_is_typed_and_fails_the_gpu_gate)"},"proof_policy":"tests/gpu-proof.toml (V4-03): require_gpu = true makes a GPU-execution proof without an adapter FAIL with a message starting NOT_PROVEN: no adapter; require_gpu = false lets it print that line and pass (the round counts it, exit 73); HSK_STUDIO_TEST_REQUIRE_GPU=1 only strengthens the file (test no_adapter_is_not_a_green_gpu_proof_when_the_gpu_is_required)","plan":"hsk_studio_pigment::render_plan::RenderPlan; admit() runs first (cancel, stale revision, validation, per-operator class); root group or leaf of solid and tile layers; nested isolated groups (one chunk buffer per nesting level) and pass-through groups; per-layer coverage masks; clip-to-base runs","blend":{"owner":"hsk_studio_pigment::blend_math (reference); WGSL reproduces composite_over in f32","supported":"normal plus every layer-applicable separable, non-separable or whole-pixel mode for which pigment has a usable formula (class Exact or Approximate): Exact separable darken, multiply, colour_burn, lighten, screen, colour_dodge, overlay, soft_light, hard_light, difference, exclusion; Exact non-separable hue, saturation, colour, luminosity; Approximate separable linear_burn, linear_dodge_add, vivid_light, linear_light, pin_light, hard_mix, subtract, divide; Approximate whole-pixel darker_colour, lighter_colour; the WGSL mode switch is generated from pigment MODES facts (gpu_blend_qualifies) so pigment owns the list, kernel.rs owns only the per-mode formula bodies; a qualifying mode without a body is unsupported (tests admission_refusals_run_without_adapter, gpu_modes_masks_groups_clip_parity)","exactness":"fitted (tolerance-equal, not bit-exact: GPU fused multiply-add and division) for a mode pigment marks Exact; a mode pigment marks Approximate keeps that class in the ledger and receipt (the backend only lowers a class), so a Fitted or Exact floor refuses it as Unsupported{mode, approximate}; tile/solid/isolated group/pass-through group/mask exact (structure and f32 bits preserved; mask coverage is converted on the host exactly as render-cpu does); fill_opacity approximate (folded as a product); a leaf root (solid or tile root, no layer) runs one Normal kernel pass over transparent, so the receipt records normal: fitted and an Exact floor refuses it (test leaf_root_reports_the_blend_kernel_class)","refused":"dissolve (stochastic, plan carries no seed), tool-only and unspecified modes (refused, not replaced by normal: test admission_refusals_run_without_adapter), vector, pass-through with opacity or fill below 1, non-isolated blended groups, mask density other than 1 on the v1 path (the extension envelope admits it), mask on a pass-through layer (mask_on_pass_through, refused by shared admission for every backend), premultiplied alpha (alpha_premultiplied, declared Unsupported through extension_exactness so shared admission refuses it), samples outside [0,1]: Unsupported at admission or source preparation, before any upload (test defence_in_depth_refusal_keys_are_pigments)"},"extensions":{"path":"execute_extended(plan, PlanExtensions): admit_extended (shared admission), prepare, run; an empty envelope without a mask density below 1 is the v1 plan (test ext_mask_density_invert_feather_parity compares pixels, plan digest, ledger and peak bytes with the v1 path)","operators":"mask density (shader step over host-converted, inverted, feathered coverage); mask feather (host separable Gaussian blur over pigment feather_kernel, replicate clamp at the plane border, only over the layer region); Blend-If on unclipped layers (up to 4 channel entries in plan order, identity entries dropped, the weight multiplies the layer opacity; for an adjustment layer the source colour is f(backdrop), as pigment documents the layer's content; agreement with pigment evaluate_stack for an adjustment layer and for a plain layer is tested by ext_blend_if_agrees_with_pigment_evaluate_stack); adjustment layers on the running backdrop (group, pass-through parent or clip-run unit): levels, curves (4096-entry table per channel built from pigment PreparedCurve, linear interpolation), hue_saturation (master and colorize), exposure, invert, threshold, posterize. WGSL is a transcription of pigment adjust_math and coverage_math, not a second definition of the maths; parity tests ext_mask_density_invert_feather_parity, ext_blend_if_parity, ext_adjustment_layer_parity","exactness":"a supported envelope operator reports the lower class of pigment's declared class and Fitted (f32 GPU arithmetic is tolerance-equal, not bit-exact), so the reported class is never better than pigment's: adjustment_layer, levels/curves/hue_saturation/exposure/threshold/posterize, blend_if, mask_density, mask_feather and every effect kind approximate, invert fitted (tests ext_refusals_and_capabilities_run_without_adapter, fx_admission_and_refusals_run_without_adapter); a Fitted floor refuses an adjustment layer or an effect","refused":"knockout, brightness_contrast (modern is pigment's typed refusal, legacy has no GPU body), Blend-If on the base of a clipping run (blend_if_clip_base) or on a clipped layer (blend_if_clipped_layer): no public source defines it, so pigment admission refuses it for every backend and prepare keeps the check under the same keys, tests fx_admission_and_refusals_run_without_adapter and ext_blend_if_parity, effects together with Blend-If on one layer (effects_with_blend_if): refused by shared admission for every backend (ExtOperator::EffectsWithBlendIf is intrinsically Unsupported) before any upload, and kept under the same key in prepare as defence in depth (tests ext_refusals_and_capabilities_run_without_adapter, fx_admission_and_refusals_run_without_adapter, defence_in_depth_refusal_keys_are_pigments); a feather whose scratch exceeds max_working_bytes is BudgetExceeded and one costing more than 2^31 tap operations is Unsupported{mask_feather_cost}, both before any device work (same test)","buffers":"a 288 byte parameter block and a curve-table binding (65536 bytes with curves, 16 otherwise) exist only when a layer uses Blend-If or an adjustment; four compute pipelines (composite, composite_ext, adjust over kernel.wgsl and fx over fx.wgsl) are built together, so a shader failure is the typed pipeline failure","effects":{"kinds":"drop_shadow, colour_overlay, stroke (wave 1), inner_shadow, outer_glow, inner_glow (wave 2), colour source and the Softer technique as in pigment effect_math; gradient glow, glow range, jitter and the Precise technique stay pigment's typed refusals (test fx_admission_and_refusals_run_without_adapter)","maths":"pigment is the owner: shadow_split, shadow_offset, feather_kernel and effect_support_px are called here; the per-pixel loops (source plane, disc dilation, separable blur, shift, combine) are WGSL transcriptions in fx.wgsl, parity-tested against render_layer_reference (tests fx_wave1_parity_vs_pigment_render_layer_reference, fx_wave2_parity_vs_pigment_render_layer_reference, fx_stack_mask_group_and_nesting_parity); the blur taps accumulate in binary32 where pigment uses binary64","execution":"a plan with effects evaluates every chunk as a frame, the chunk grown by the largest sum of effect margins along nested layers; the layer content (mask applied to its alpha) is rendered into the level below, each matte is built by the matte passes into the mask buffer and composited as a solid colour with the effect's mode and effect opacity times layer opacity; behind-content effects, the content, then over-content effects, each in list order; passes cover the layer bounds plus the margin and read the constant a sample beyond that region reads in pigment's reference plane","exactness":"approximate (pigment's class); nested effects (a layer with effects whose content holds a layer with effects, effects_nested) are declared supported through extension_exactness and report approximate (tests fx_stack_mask_group_and_nesting_parity, ext_refusals_and_capabilities_run_without_adapter); Photoshop parity is not proven","limits":"frame buffers come out of the chunk budget (BudgetExceeded when even an 8 pixel chunk does not fit); a pass costs window x pixels and the chunk shrinks to stay under 2^31, Unsupported{effect_cost} when it cannot (test fx_stack_mask_group_and_nesting_parity); blur kernels are charged to max_working_bytes while the effects compile (test fx_admission_and_refusals_run_without_adapter); a mask read beyond the target replicates the nearest plane texel"}},"blur":"envelope LayerExtension.blur (lane SMB-COMPOSITE-NEW-KINDS): ExtOperator::Blur(layer|backdrop) supported (pigment class approximate); blur.wgsl transcribes pigment blur_math in binary32: horizontal premultiplied pass into a frame scratch plane, vertical pass with unpremultiply, backdrop mix k = shape alpha * layer opacity; layer blur grows the frame margin by its support, a backdrop blur by its support plus the margin of the layers below; a blur pass is bounded like an effect pass (taps x frame pixels <= FX_PASS_MAX_OPS); measured max |delta| vs the pigment composition (alpha and premultiplied colour) 1.19e-7, tolerance 1e-5 (tests/gpu_blur.rs on a live adapter; no adapter = NOT_PROVEN per gpu-proof.toml)","transform":"envelope LayerExtension.transform on a tile layer (lane SMB-PIGMENT-TRANSFORM): ExtOperator::Transform(nearest_neighbour|bilinear|bicubic) declared, reported approximate (pigment class); the host computes every pixel's sample site with pigment transform_math::PreparedTransform::sample_site (binary64: exact-texel rule, nearest choice, clamp hard edge, first tap, fractions) and uploads the tile window the taps read; resample.wgsl evaluates bilinear or Catmull-Rom weights and the premultiplied accumulation in binary32 into the composite source buffer; a linked mask is resampled on the host by pigment sample_coverage (bit-identical to render-cpu); parity vs the pigment reference composited by pigment: max deviation 1.79e-7 (alpha, premultiplied and straight colour) over every filter and edge mode, under the 2e-6 tolerance (tests gpu_transform gpu_resample_parity_vs_pigment_reference, gpu_linked_mask_follows_the_content); identity and integer translations equal the untransformed plan bit for bit and a quarter turn copies texels exactly (test gpu_identity_integer_and_quarter_turn_equal_the_untransformed_plan); hostile matrices, a non-tile input, transform with effects and a Fitted floor are refused at admission before any device work (test transform_admission_refusals_run_without_adapter); buffers: 48 byte parameter block, 16 bytes of sample site per frame texel and a window holding the largest transformed tile, all charged before creation","clip_to_base":"supports_clip_to_base() = true. Run [base, clipped...] (a clipped layer carries MaskInput::clip_to_base()) is one isolated unit G on its own chunk buffer: G = base content with the base mask (no opacity/fill/mode); each clipped layer composites onto G with its own mode/opacity/fill and source alpha times the base alpha, alpha of G held at the base alpha; G composites onto the parent with the BASE layer mode/opacity/fill. Class Approximate (pigment rule unverified against Photoshop). Base that is a pass-through group is refused; Blend-If on the base or on a clipped layer is refused (blend_if_clip_base, blend_if_clipped_layer; tests fx_admission_and_refusals_run_without_adapter, ext_blend_if_parity)","formats":{"colour":"rgb_f32le","alpha":"f32le straight, separate plane","chunk":"tightly packed row-major, sink receives rect + both planes"},"memory":{"residency":"pure-Rust LRU with pins and a hard budget, checked byte arithmetic (evict or BudgetExceeded near u64::MAX: test residency_accounting_never_overflows); every device buffer is charged before it is created and released on every exit; peak and evictions are counted","buffers_per_call":"one chunk destination per group nesting level (1 + isolated depth, plus one per nested layer with effects) + staging (+ src when tiles) (+ f32 mask when masks or effects) + 64 byte params (+ the envelope parameter block and curve table when the envelope needs them) (+ three f32 matte planes and a 12080 byte parameter block when a layer has effects; the level, src and mask buffers are then frame-sized)","chunk":"shrinks from 512 until all buffers fit min(request.max_working_bytes, residency budget, device buffer limits); smaller than 64 texels -> BudgetExceeded","units":"RGBA f32 = 16 bytes per texel"},"failure":"cancel/deadline between chunks and layers; stale revision, invalid plan, unsupported operator, unresolved or mismatching source refuse before the first device call; sink error aborts; scratch released on every exit; receipt only after the last chunk","privacy":"no pixel, profile or path bytes in telemetry; adapter name only in the receipt identity text","pending":["dissolve (stochastic): needs a plan-level seed and a WGSL u64 hash equivalent to pigment site_unit","knockout, legacy brightness_contrast on the GPU, effect passes restricted to the layer window (the passes run over the whole layer region), binary64 blur accumulation","effects: Photoshop parity (D5 cases 12-17)","vector coverage","content-addressed tile cache across executions (ResidentKey::Tile)","compute-shader feather (the blur is on the host)","f16/HDR accumulation, multi-GPU, surface presentation (host)","backend-qualified oracle on discrete GPU, Vulkan and Metal: only the backend named in the lane file is proven"]}"#;
